from collections import Counter,defaultdict,deque

def comps(g,bg=None):
 h,w=len(g),len(g[0]); bg=Counter(v for row in g for v in row).most_common(1)[0][0] if bg is None else bg
 seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   co=g[r][c]
   if co==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   for x,y in q:
    cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==co:
      seen.add((a,b)); q.append((a,b))
   minr=min(x for x,y in cells); minc=min(y for x,y in cells)
   shape=tuple(sorted((x-minr,y-minc) for x,y in cells))
   out.append(dict(color=co,cells=cells,shape=shape,bbox=(minr,minc,max(x for x,y in cells),max(y for x,y in cells)),n=len(cells),centroid=(sum(x for x,y in cells)/len(cells),sum(y for x,y in cells)/len(cells))))
 return bg,out
