def analyze_candidates(g, use_near=False):
 h,w=len(g),len(g[0]); bg=Counter(v for row in g for v in row).most_common(1)[0][0]
 _,objects=comps(g,bg)
 for obj in objects:
  cells=obj['cells']; minr,minc,maxr,maxc=obj['bbox']; s=set(cells)
  corners=[]
  for pr in range(minr,maxr+1):
   for pc in range(minc,maxc+1):
    l=({(x,pc) for x in range(minr,maxr+1)}|{(pr,y) for y in range(minc,maxc+1)})
    if l==s and len(l)>=5:corners.append((pr,pc))
  obj['touches']=any(x==0 or x==h-1 or y==0 or y==w-1 for x,y in cells)
  obj['marker']=obj['touches'] and bool(corners)
  obj['corners']=corners
 markers=[o for o in objects if o['marker']]
 if not markers:markers=[o for o in objects if o['touches']]
 if not markers:return None
 marker=max(markers,key=lambda o:o['n'])
 mcol=marker['centroid'][1]
 mrgt=any(c==w-1 for r,c in marker['cells']); mleft=any(c==0 for r,c in marker['cells']); go_right=mleft or not mrgt
 group=defaultdict(list)
 for o in objects:
  if o is not marker:group[o['shape']].append(o)
 out=[]
 for shape,obs in group.items():
  pairs=[obs] if len(obs)==2 else []
  if len(obs)>2:
   bycol=defaultdict(list)
   for o in obs:bycol[o['color']].append(o)
   pairs.extend(p for p in bycol.values() if len(p)==2)
  for pair in pairs:
   x,y=pair; c1=x['centroid'][1]; c2=y['centroid'][1]
   if (c1-mcol)*(c2-mcol)<=0 and c1!=c2:
    target=max(pair,key=lambda o:o['centroid'][1]) if go_right else min(pair,key=lambda o:o['centroid'][1])
    reason='cross'
   else:
    f=max if not use_near else min
    target=f(pair,key=lambda o:(o['centroid'][0]-marker['centroid'][0])**2+(o['centroid'][1]-marker['centroid'][1])**2)
    reason='dist'
   out.append((shape,[(o['color'],o['bbox'],o['centroid'],o['n']) for o in pair],(target['color'],target['bbox']),reason,go_right,mcol,marker['bbox']))
 return out
